def _unpack():
    enc = base64.b85decode(_PROTECTED_PAYLOAD.strip().encode("ascii"))
    k = hashlib.sha256(_SIG.encode("utf-8")).digest()
    ks = bytearray()
    c = 0
    while len(ks) < len(enc):
        ks.extend(hashlib.sha256(k + c.to_bytes(4, "big")).digest())
        c += 1
    raw = bytes([a ^ b for a, b in zip(enc, ks[:len(enc)])])
    return zlib.decompress(raw).decode("utf-8")

if __name__ == "__main__":
    _code = _unpack()
    _globals = {
        "__name__": "__main__",
        "__file__": __file__,
        "__doc__": None,
        "__package__": None
    }
    exec(compile(_code, __file__, "exec"), _globals)
